								doc.aksi === 'Ajukan Ulang'
									? 'Ajukan Ulang'
									: 'Alasan Pulang Cepat'
							}}
						</h2>
						<p class="mt-1 text-sm text-ui-ink-gray-500">
							{{ tanggalPanjang(doc.tanggal) }} · pulang cepat
							{{ durasiMenit(doc.menit_pulang_cepat) }}
						</p>

						<label
							for="alasan"
							class="mt-4 block text-sm font-medium text-ui-ink-gray-700"
							>Alasan <span class="text-ui-ink-red-500">*</span></label
						>
						<textarea
							id="alasan"
							ref="inputAlasan"
							v-model="alasan"
							rows="4"
							maxlength="1000"
							placeholder="Jelaskan kenapa Anda pulang lebih awal hari itu…"
							class="mt-1.5 w-full resize-none rounded-xl border border-ui-line-gray-200 bg-ui-surface-gray-50 p-3 text-base text-ui-ink-gray-900 placeholder:text-ui-ink-gray-400 focus:border-primary focus:bg-ui-surface focus:outline-none"
						></textarea>

						<label class="mt-3 block text-sm font-medium text-ui-ink-gray-700"
							>Lampiran
							<span class="font-normal text-ui-ink-gray-400">(opsional)</span></label
						>
						<input
							type="file"
							class="mt-1.5 w-full text-sm text-ui-ink-gray-600 file:mr-3 file:rounded-lg file:border-0 file:bg-ui-surface-gray-100 file:px-3 file:py-2 file:text-sm file:font-medium file:text-ui-ink-gray-700"
							:disabled="mengunggah"
							@change="unggah"
						/>
						<p v-if="mengunggah" class="mt-1 text-xs text-ui-ink-gray-500">
							Mengunggah…
						</p>
						<p v-else-if="lampiran" class="mt-1 text-xs text-ui-ink-green-700">
							Lampiran siap dikirim.
						</p>

						<p v-if="modalError" class="mt-3 text-sm text-ui-ink-red-600">
							{{ modalError }}
						</p>

						<div class="mt-5 flex gap-2">
							<button
								type="button"
								class="flex-1 rounded-xl border border-ui-line-gray-200 py-3 text-base font-medium text-ui-ink-gray-700 transition active:bg-ui-surface-gray-100"
								:disabled="mengirim"
								@click="tutupModal"
							>
								Batal
							</button>
							<button
								type="button"
								class="flex-1 rounded-xl bg-primary py-3 text-base font-semibold text-ui-onPrimary transition active:opacity-90 disabled:opacity-60"
								:disabled="mengirim || mengunggah || !alasan.trim()"
								@click="kirim"
							>
								{{ mengirim ? 'Mengirim…' : 'Kirim' }}
							</button>
						</div>
