</template>

<script setup>
/**
 * Detail satu pulang cepat, dan tempat karyawan mengisi alasan. Mencerminkan
 * KeterlambatanDetail.vue; helper status/tanggal dipakai ulang karena statusnya
 * sama persis. Tombol isi alasan hanya muncul bila server bilang `boleh_diisi`.
 */
import { computed, nextTick, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import {
	durasiMenit,
	garisRiwayat,
	jam,
	statusBadge,
	tanggalPanjang,
	tanggalRingkas,
	waktuRingkas,
} from '../data/keterlambatanStatus'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'

const MAKS_MB = 5

const props = defineProps({ name: { type: String, required: true } })

const route = useRoute()

const dariKetua = computed(() => route.query.dari === 'ketua')
const tujuanKembali = computed(() =>
	dariKetua.value ? { name: 'KepulanganCepatKetua' } : { name: 'KepulanganCepat' }
)

const doc = ref(null)
const error = ref('')

const aksi = ref([])
const aksiTerbuka = ref(false)
const menjalankan = ref('')
const tolakAksi = ref(null)
const alasanTolak = ref('')
const galatTolak = ref('')

const tampilkanIdentitas = computed(
	() => !!doc.value?.nama_karyawan && (dariKetua.value || aksi.value.length > 0)
)

function inisial(nama) {
	return String(nama || '?')
		.split(/\s+/)
		.slice(0, 2)
		.map((w) => w[0] || '')
		.join('')
		.toUpperCase()
}

function merusak(action) {
	const t = aksi.value.find((a) => a.action === action)
	return t ? t.next_state === 'Tidak Dimaafkan' : /reject|tolak/i.test(action || '')
}

function labelAksi(a) {
	if (a.next_state === 'Dimaafkan') return 'Maafkan'
	if (a.next_state === 'Tidak Dimaafkan') return 'Tolak'
	if (a.next_state === 'Menunggu Approval Ketua') return 'Setujui'
	return a.action
}

const modal = ref(false)
const alasan = ref('')
const lampiran = ref('')
const modalError = ref('')
const mengirim = ref(false)
const mengunggah = ref(false)
const inputAlasan = ref(null)

// Datang dari tombol "Tandai Pulang Cepat" (query isi=1): modal alasan dibuka
// sekali begitu detail termuat, sesuai alur "modal langsung muncul".
let autoIsiDone = false

const detail = createResource({
	url: 'juragan.api.portal.kepulangan_cepat.get_detail',
	auto: false,
	makeParams() {
		return { name: props.name }
	},
	onSuccess(data) {
		doc.value = data
		if (route.query.isi && data?.boleh_diisi && !autoIsiDone) {
			autoIsiDone = true
			bukaModal()
		}
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
	},
})

const kirimAlasan = createResource({
	url: 'juragan.api.portal.kepulangan_cepat.kirim_alasan',
	auto: false,
	makeParams() {
		return { name: props.name, alasan: alasan.value.trim(), lampiran: lampiran.value || null }
	},
	onSuccess(data) {
		doc.value = data
		mengirim.value = false
		tutupModal()
	},
	onError(err) {
		modalError.value = err?.messages?.[0] || err?.message || String(err)
		mengirim.value = false
	},
})

async function bukaModal() {
	alasan.value = doc.value?.alasan || ''
	lampiran.value = doc.value?.lampiran || ''
	modalError.value = ''
	modal.value = true
	await nextTick()
	inputAlasan.value?.focus()
}

function tutupModal() {
	if (mengirim.value) return
	modal.value = false
}

function kirim() {
	if (!alasan.value.trim()) return
	modalError.value = ''
	mengirim.value = true
	kirimAlasan.fetch()
}

async function unggah(e) {
	const file = e.target.files?.[0]
	if (!file) return
	if (file.size > MAKS_MB * 1024 * 1024) {
		modalError.value = `Ukuran file maksimal ${MAKS_MB} MB.`
		e.target.value = ''
		return
	}

	mengunggah.value = true
	modalError.value = ''
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		lampiran.value = json.message?.file_url || ''
	} catch (err) {
		modalError.value = err.message || String(err)
		e.target.value = ''
	} finally {
		mengunggah.value = false
	}
}

const aksiRes = createResource({
	url: 'juragan.api.portal.kepulangan_cepat.get_aksi',
	method: 'GET',
	auto: false,
	makeParams() {
		return { name: props.name }
	},
	onSuccess(data) {
		aksi.value = data || []
	},
	onError() {
		aksi.value = []
	},
})

const putuskanRes = createResource({
	url: 'juragan.api.portal.kepulangan_cepat.putuskan',
	method: 'POST',
	auto: false,
	onError() {},
})

function pilihAksi(a) {
	if (a.next_state === 'Tidak Dimaafkan') {
		tolakAksi.value = a
		alasanTolak.value = ''
		galatTolak.value = ''
		aksiTerbuka.value = false
		return
	}
	jalankan(a)
}

function batalTolak() {
	if (menjalankan.value) return
	tolakAksi.value = null
	galatTolak.value = ''
}

function kirimTolak() {
	if (!alasanTolak.value.trim()) {
		galatTolak.value = 'Isi alasan penolakan dulu.'
		return
	}
	jalankan(tolakAksi.value, alasanTolak.value.trim())
}

async function jalankan(a, alasanPenolakan) {
	if (menjalankan.value) return
	menjalankan.value = a.action
	try {
		await putuskanRes.submit({
			name: props.name,
			action: a.action,
			alasan_penolakan: alasanPenolakan,
		})
		notifySuccess(
			a.next_state === 'Dimaafkan'
				? 'Pulang cepat dimaafkan.'
				: a.next_state === 'Tidak Dimaafkan'
				? 'Pulang cepat ditolak.'
				: 'Diteruskan ke Ketua.'
		)
		tolakAksi.value = null
		aksiTerbuka.value = false
		detail.fetch()
		aksiRes.fetch()
	} catch (e) {
		notifyError(e, 'Gagal menyimpan keputusan')
	} finally {
		menjalankan.value = ''
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	detail.fetch()
	aksiRes.fetch()
})
</script>
